#include "test_support.h"
#include "../modules/settings_policy.h"
struct Store final:SettingsStore {Settings value;bool fail=false;unsigned writes=0;Settings read()override{return value;}void write(const Settings& s)override{if(fail)throw std::runtime_error("Store failed");value=s;++writes;}};
int main(){Suite s;
 s.test("defaults enable presence and keep application override empty",[]{Store store;auto value=store.read();require(value.enabled&&value.custom_application_id.empty(),"Defaults expose an ID or disable presence");});
 s.test("toggle and custom application round trip",[]{Store store;unsigned notifications=0;apply_settings(store,{false,"123456789012345678"},[&]{++notifications;});require(!store.read().enabled&&store.read().custom_application_id=="123456789012345678","Settings not persisted");apply_settings(store,{true,""},[&]{++notifications;});require(store.read().enabled&&store.read().custom_application_id.empty()&&notifications==2,"Defaults/reset not persisted");});
 s.test("invalid snowflakes never mutate settings or notify",[]{Store store;unsigned n=0;for(const auto* id:{"0","00123","12 abc","-12","18446744073709551616"})throws<std::invalid_argument>([&]{apply_settings(store,{false,id},[&]{++n;});},"Invalid ID accepted");require(store.writes==0&&n==0&&store.read().enabled,"Invalid transaction mutated settings");require(valid_application_id("18446744073709551615"),"Maximum uint64 should be accepted");});
 s.test("failed storage does not notify runtime",[]{Store store;store.fail=true;unsigned n=0;throws<std::runtime_error>([&]{apply_settings(store,{false,""},[&]{++n;});},"Store failure swallowed");require(n==0&&store.read().enabled,"Failure notified runtime");});
 s.test("portable profile wins over AppData",[]{std::vector<std::filesystem::path> checked;auto path=choose_cache_folder("portable/profile/cache","appdata/cache",[&](const auto& p){checked.push_back(p);return true;});require(path=="portable/profile/cache"&&checked.size()==1,"Fallback used despite writable profile");});
 s.test("unwritable or unavailable profile falls back",[]{auto path=choose_cache_folder("bad/profile","appdata/cache",[](const auto& p){return p=="appdata/cache";});require(path=="appdata/cache","AppData fallback missing");require(choose_cache_folder({},"application-support/cache",[](const auto&){return true;})=="application-support/cache","Missing profile fallback missing");});
 s.test("both unwritable disables persistence, not playback",[]{require(choose_cache_folder("bad/profile","bad/fallback",[](const auto&){return false;}).empty(),"Unwritable folders should select memory-only mode");require(choose_cache_folder("bad/profile","good",[](const auto& p){if(p=="bad/profile")throw std::runtime_error("Denied");return true;})=="good","Probe exception prevented fallback");});
 return s.finish();}
